INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Conclusion$batch01$, $batch01$No wealthy person should serve on Grandville's Planning Committee.$batch01$), (1, $batch01$Evidence$batch01$, $batch01$A number of Grandville's wealthiest citizens have been criminals. Committee members must have irreproachable ethics.$batch01$), (2, $batch01$Evaluate$batch01$, $batch01$Granted, criminals fail the ethics requirement. How does “a number of the wealthiest” tell us that *every* wealthy candidate fails it? Those cases could be exceptions. A wealthy person with an irreproachable record would meet the stated requirement. The evidence does not cover the entire class the conclusion excludes.$batch01$), (3, $batch01$Goal$batch01$, $batch01$Look for overgeneralizing from possibly exceptional wealthy criminals to all wealthy people.$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT106-S3-Q2$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$The criminal cases and the proposed exclusion might make this seem like a cause-and-effect claim. Check the actual conclusion: it says no wealthy person should be appointed, not that wealth caused crime or that a committee appointment caused an outcome. The evidence is about a *number* of wealthy criminals, and the conclusion bars *all* wealthy people. The change in quantity, not cause and effect, is the problem.$batch01$), ($batch01$B$batch01$, $batch01$Nothing is said to follow another event in time, and no causal inference is made from a sequence.$batch01$), ($batch01$C$batch01$, $batch01$No action's unintended consequence is at issue. The conclusion is a hiring exclusion.$batch01$), ($batch01$D$batch01$, $batch01$Criminal conduct and an ethics rule are the stated grounds. The problem is how far the evidence extends, not whether those standards are subjective or objective.$batch01$), ($batch01$E$batch01$, $batch01$“A number” of wealthy criminals may be exceptional. It cannot justify a ban on *every* wealthy person. This is the Sampling or Hasty Generalization move: the observed cases may not represent the wider class.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT106-S3-Q2$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
